[
  {
    "statement": "Several practices for preventing disease in aquaculture have been documented.",
    "citations": []
  },
  {
    "statement": "Establishing fallowing systems can reduce parasites and disease.",
    "citations": [
      "1026"
    ]
  },
  {
    "statement": "A study in Scotland recorded lower lice numbers on Atlantic salmon in cages that used a fallowing system.",
    "citations": [
      "1026"
    ]
  },
  {
    "statement": "Breeding for resistance traits has been shown to be effective.",
    "citations": [
      "735"
    ]
  },
  {
    "statement": "A study in Norway found that a salmon family bred for high resistance to infectious pancreatic necrosis had increased survival levels compared to a family bred for low resistance.",
    "citations": [
      "735"
    ]
  },
  {
    "statement": "The practice of leaving fallow periods during fish farming has been studied.",
    "citations": [
      "2191"
    ]
  },
  {
    "statement": "Three studies examined the effects of fallow periods on invertebrate populations.",
    "citations": [
      "2191"
    ]
  },
  {
    "statement": "Fallow periods allow invertebrate community composition to become more similar to pre-farming conditions.",
    "citations": [
      "2191"
    ]
  },
  {
    "statement": "Sourcing spat and juveniles from areas or hatcheries not infested with diseases or non-native or problematic species is a recommended practice.",
    "citations": [
      "2159"
    ]
  },
  {
    "statement": "Reducing aquaculture stocking densities is a recommended practice.",
    "citations": [
      "2186"
    ]
  },
  {
    "statement": "Locating aquaculture systems in areas with fast currents is a recommended practice.",
    "citations": [
      "2188"
    ]
  },
  {
    "statement": "Improving fish food and pellets to reduce waste production is a recommended practice.",
    "citations": [
      "2192"
    ]
  }
]

[
  {
    "statement": "Based on the available evidence, vaccinations show more extensive documented effectiveness for improving salmon survival rates compared to altering cage size.",
    "citations": [
      "733",
      "742"
    ]
  },
  {
    "statement": "Controlled studies from Iceland found higher survival rates in vaccinated salmon compared to unvaccinated control groups after exposure to disease-causing bacteria Aeromonas salmonicida spp.achromogenes.",
    "citations": [
      "733"
    ]
  },
  {
    "statement": "Controlled studies from Norway found higher survival rates in vaccinated salmon compared to unvaccinated control groups after exposure to disease-causing bacteria Yersinia ruckeri.",
    "citations": [
      "733"
    ]
  },
  {
    "statement": "Controlled studies in Australia and Canada reported higher survival in salmon infected with marine flexibacteriosis post vaccination.",
    "citations": [
      "733"
    ]
  },
  {
    "statement": "Controlled studies in Australia and Canada reported higher survival in salmon infected with bacterial kidney disease post vaccination.",
    "citations": [
      "733"
    ]
  },
  {
    "statement": "Two controlled studies in Norway reported higher survival rates for salmon vaccinated against infectious salmon anaemia.",
    "citations": [
      "733"
    ]
  },
  {
    "statement": "For cage size alteration, only one replicated study in Australia was identified.",
    "citations": [
      "742"
    ]
  },
  {
    "statement": "A replicated study in Australia recorded lower levels of amoebic gill disease in salmon kept within larger compared to smaller cages.",
    "citations": [
      "742"
    ]
  },
  {
    "statement": "The vaccination intervention demonstrates broader evidence across multiple disease types and geographic locations with consistently higher survival rates.",
    "citations": [
      "733"
    ]
  },
  {
    "statement": "Evidence for the effectiveness of altering cage size is limited to one study focusing specifically on amoebic gill disease reduction.",
    "citations": [
      "742"
    ]
  }
]

[
  {
    "statement": "The action documents contain limited information about international regulations for genetically modified ingredients in salmon feed.",
    "citations": []
  },
  {
    "statement": "One action document contains studies from Norway examining the use of genetically modified soybeans in Atlantic salmon diets.",
    "citations": [
      "928"
    ]
  },
  {
    "statement": "Three controlled, replicated studies in Norway found no difference in the growth rate of Atlantic salmon that were fed diets containing either genetically modified or non-genetically modified soybeans.",
    "citations": [
      "928"
    ]
  },
  {
    "statement": "One randomised, replicated, controlled study in Norway found no differences in the histology of fish fed diets containing either genetically modified or non-genetically modified soybeans.",
    "citations": [
      "928"
    ]
  },
  {
    "statement": "The action documents do not contain specific information about international regulatory frameworks for the use of genetically modified ingredients in salmon feed.",
    "citations": []
  },
  {
    "statement": "The action documents do not contain specific information about approval processes for the use of genetically modified ingredients in salmon feed.",
    "citations": []
  },
  {
    "statement": "The action documents do not contain specific information about compliance requirements for the use of genetically modified ingredients in salmon feed.",
    "citations": []
  }
]
